import React from 'react';
import { Box, Paper, Typography } from '@mui/material';
import {
  Assessment as AssessmentIcon,
  Description as DocumentsIcon,
  Flag as TargetsIcon,
  Forest as OffsetsIcon,
  Savings as SavingsIcon,
  Summarize as ReportingIcon,
  VerifiedUser as ComplianceIcon,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';

const QUICK_ACTIONS = [
  { label: 'Carbon assessment', path: '/carbon-footprint?section=start-assessment', icon: AssessmentIcon },
  { label: 'Carbon offsets', path: '/carbon-marketplace?tab=0', icon: OffsetsIcon },
  { label: 'Documents', path: '/data', icon: DocumentsIcon },
  { label: 'Reporting', path: '/reporting?tab=0', icon: ReportingIcon },
  { label: 'Emissions targets', path: '/emissions-reduction-targets', icon: TargetsIcon },
  { label: 'Carbon savings', path: '/carbon-savings', icon: SavingsIcon },
  { label: 'Compliance', path: '/compliance', icon: ComplianceIcon },
] as const;

export const DashboardQuickActions: React.FC = () => {
  const navigate = useNavigate();
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';

  return (
    <Box>
      <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1.5 }}>
        Quick actions
      </Typography>
      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: {
            xs: 'repeat(2, 1fr)',
            sm: 'repeat(3, 1fr)',
            md: 'repeat(4, 1fr)',
            lg: 'repeat(7, 1fr)',
          },
          gap: 1.5,
        }}
      >
        {QUICK_ACTIONS.map(({ label, path, icon: Icon }) => (
          <Paper
            key={path}
            component="button"
            type="button"
            onClick={() => navigate(path)}
            variant="outlined"
            sx={{
              p: 1.5,
              textAlign: 'center',
              cursor: 'pointer',
              border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.28 : 0.14)}`,
              bgcolor: isDark ? alpha(theme.palette.common.white, 0.03) : 'background.paper',
              transition: 'transform 0.2s ease, box-shadow 0.2s ease',
              '&:hover': {
                transform: 'translateY(-2px)',
                boxShadow: isDark ? '0 8px 24px rgba(0,0,0,0.35)' : '0 8px 20px rgba(15, 23, 42, 0.08)',
                borderColor: alpha(theme.palette.primary.main, 0.4),
              },
            }}
          >
            <Icon color="primary" sx={{ fontSize: 28, mb: 0.5 }} />
            <Typography variant="caption" sx={{ fontWeight: 600, display: 'block', lineHeight: 1.3 }}>
              {label}
            </Typography>
          </Paper>
        ))}
      </Box>
    </Box>
  );
};
