import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  FormControl,
  FormControlLabel,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Switch,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { reportingTabHref } from '../../constants/reportingTabs';
import ApiService from '../../services/api';
import {
  complianceWorkflowStatusLabel,
  EXPORT_COMPLIANCE_GROUPS,
  EXPORT_COMPLIANCE_SECTIONS,
  unwrapComplianceHubPayload,
} from '../../constants/complianceHub';
import { useUrlSectionParam } from '../../hooks/useUrlSectionParam';
import ComplianceTrackShell from './ComplianceTrackShell';
import ComplianceReadinessGrid from './ComplianceReadinessGrid';
import ComplianceJsonPanel from './ComplianceJsonPanel';

const SECTION_IDS = EXPORT_COMPLIANCE_SECTIONS.map((s) => s.id);

type ExportComplianceTrackProps = {
  variant?: 'msme' | 'enterprise';
};

const CBAM_CATEGORIES = [
  'cement',
  'iron_steel',
  'aluminium',
  'fertilisers',
  'electricity',
  'hydrogen',
];

const ExportComplianceTrack: React.FC<ExportComplianceTrackProps> = ({ variant = 'msme' }) => {
  const isEnterprise = variant === 'enterprise';
  const [section, setSection] = useUrlSectionParam('overview', SECTION_IDS);
  const [period, setPeriod] = useState('annual');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [track, setTrack] = useState<Record<string, unknown> | null>(null);
  const [exportProfile, setExportProfile] = useState<Record<string, unknown>>({});
  const [saving, setSaving] = useState(false);
  const [newQuestionnaire, setNewQuestionnaire] = useState({
    buyerName: '',
    framework: 'csrd',
    buyerContactEmail: '',
  });
  const [exportPack, setExportPack] = useState<unknown>(null);
  const [downloadingBundle, setDownloadingBundle] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getComplianceExportTrack({ period });
      const data = unwrapComplianceHubPayload<Record<string, unknown>>(res);
      setTrack(data);
      if (data?.exportProfile) {
        setExportProfile(data.exportProfile as Record<string, unknown>);
      }
    } catch (e) {
      setTrack(null);
      setError(e instanceof Error ? e.message : 'Failed to load export compliance track');
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    load();
  }, [load]);

  const modules = (track?.modules || {}) as Record<string, unknown>;
  const readiness = (track?.readiness || {}) as Record<string, string>;

  const saveExportProfile = async () => {
    setSaving(true);
    try {
      await ApiService.updateComplianceExportProfile(exportProfile);
      await load();
    } finally {
      setSaving(false);
    }
  };

  const addQuestionnaire = async () => {
    if (!newQuestionnaire.buyerName.trim()) return;
    setSaving(true);
    try {
      await ApiService.createSupplierQuestionnaire(newQuestionnaire);
      setNewQuestionnaire({ buyerName: '', framework: 'csrd', buyerContactEmail: '' });
      await load();
    } finally {
      setSaving(false);
    }
  };

  const loadExportPack = async (framework: string) => {
    const res = await ApiService.getComplianceExportPack(framework, { period });
    setExportPack((res as { data?: unknown })?.data ?? null);
  };

  const downloadBuyerPackBundle = async () => {
    setDownloadingBundle(true);
    try {
      const blob = await ApiService.downloadBuyerPackExport({
        period,
        includeCbam: Boolean((exportProfile.cbamGoodsCategories as string[])?.length),
        includeEudr: Boolean(exportProfile.eudrApplicable),
      });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `buyer-pack-${period}.zip`;
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to download buyer pack bundle');
    } finally {
      setDownloadingBundle(false);
    }
  };

  const renderSection = () => {
    if (loading && !track) {
      return (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <CircularProgress />
        </Box>
      );
    }

    if (!track) {
      return null;
    }

    switch (section) {
      case 'overview':
        return (
          <>
            <Card variant="outlined" sx={{ mb: 3 }}>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Export profile
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="Primary export regions (comma-separated)"
                      fullWidth
                      value={(exportProfile.primaryRegions as string[])?.join(', ') || ''}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          primaryRegions: e.target.value.split(',').map((s) => s.trim()).filter(Boolean),
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <FormControl fullWidth>
                      <InputLabel>CBAM goods</InputLabel>
                      <Select
                        multiple
                        label="CBAM goods"
                        value={(exportProfile.cbamGoodsCategories as string[]) || []}
                        onChange={(e) =>
                          setExportProfile({
                            ...exportProfile,
                            cbamGoodsCategories:
                              typeof e.target.value === 'string'
                                ? e.target.value.split(',')
                                : e.target.value,
                          })
                        }
                        renderValue={(selected) => (selected as string[]).join(', ')}
                      >
                        {CBAM_CATEGORIES.map((cat) => (
                          <MenuItem key={cat} value={cat}>
                            {cat.replace(/_/g, ' ')}
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={Boolean(exportProfile.eudrApplicable)}
                          onChange={(e) =>
                            setExportProfile({ ...exportProfile, eudrApplicable: e.target.checked })
                          }
                        />
                      }
                      label="EUDR applies (agri/forest commodities to EU)"
                    />
                  </Grid>
                </Grid>
                <Button sx={{ mt: 2 }} variant="contained" onClick={saveExportProfile} disabled={saving}>
                  Save export profile
                </Button>
              </CardContent>
            </Card>
            <ComplianceReadinessGrid
              items={[
                { key: 'cbam', label: 'CBAM', status: readiness.cbam },
                { key: 'pcf', label: 'Product PCF', status: readiness.productPcf },
                { key: 'csrd', label: 'CSRD', status: readiness.csrd },
                { key: 'cdp', label: 'CDP', status: readiness.cdp },
                { key: 'gri', label: 'GRI 305', status: readiness.gri },
                { key: 'tcfd', label: 'TCFD', status: readiness.tcfd },
                { key: 'portal', label: 'Questionnaires', status: readiness.supplierPortal },
                { key: 'eudr', label: 'EUDR', status: readiness.eudr },
                { key: 'ecovadis', label: 'EcoVadis', status: readiness.ecovadis },
              ]}
            />
            <Alert severity="info" sx={{ mt: 2 }}>
              Download a ZIP bundle with CDP, GRI, CSRD, TCFD, EcoVadis packs, product footprints,
              and an evidence index for buyer submissions.
            </Alert>
            <Button
              variant="contained"
              sx={{ mt: 1 }}
              onClick={downloadBuyerPackBundle}
              disabled={downloadingBundle}
            >
              {downloadingBundle ? 'Preparing bundle…' : 'Download buyer pack ZIP'}
            </Button>
          </>
        );
      case 'cbam':
        return (
          <Stack spacing={2}>
            <ComplianceReadinessGrid
              items={[{ key: 'cbam', label: 'CBAM readiness', status: readiness.cbam }]}
            />
            <ComplianceJsonPanel
              title="CBAM exporter pack"
              data={modules.cbamExporter}
              filename="cbam-exporter-pack.json"
            />
            <Button component={RouterLink} to={reportingTabHref('cbam')} variant="contained">
              Open CBAM quarterly report
            </Button>
          </Stack>
        );
      case 'product-pcf':
        return (
          <Stack spacing={2}>
            <Alert severity="info">
              Maintain SKU-level footprints for EU/US buyers. Generate ISO 14067 PDFs from Disclosure
              reports.
            </Alert>
            <ComplianceJsonPanel
              title="Product footprints"
              data={modules.productFootprints}
              filename="export-product-footprints.json"
            />
            <Button
              component={RouterLink}
              to={reportingTabHref('iso14067')}
              variant="outlined"
            >
              ISO 14067 disclosure report
            </Button>
          </Stack>
        );
      case 'csrd-supplier':
        return (
          <Stack spacing={2}>
            <Button variant="outlined" onClick={() => loadExportPack('csrd')}>
              Refresh CSRD pack
            </Button>
            <ComplianceJsonPanel
              title="CSRD / ESRS supplier datapoints"
              data={exportPack || modules.csrdSupplier}
              filename="csrd-supplier-pack.json"
            />
          </Stack>
        );
      case 'cdp': {
        const cdpPack = (exportPack || modules.cdpClimate || {}) as {
          sectionsIncluded?: string[];
          c1?: Record<string, unknown>;
          c7?: { scope1?: number; scope2?: number; scope3?: number };
        };
        const sections = cdpPack.sectionsIncluded || [];
        return (
          <Stack spacing={2}>
            <Alert severity={sections.length >= 15 ? 'success' : 'info'}>
              CDP Climate Change questionnaire: {sections.length || 0}/15 sections mapped (C1–C15).
              {sections.length >= 15
                ? ' Pack ready for buyer portal upload preparation.'
                : ' Complete missing sections before CDP submission.'}
            </Alert>
            <Button variant="outlined" onClick={() => loadExportPack('cdp')}>
              Refresh CDP mapping
            </Button>
            <ComplianceJsonPanel
              title="CDP Climate Change mapping (C1–C15)"
              data={exportPack || modules.cdpClimate}
              filename="cdp-climate-pack.json"
            />
          </Stack>
        );
      }
      case 'gri':
        return (
          <Stack spacing={2}>
            <Button variant="outlined" onClick={() => loadExportPack('gri')}>
              Refresh GRI 305 pack
            </Button>
            <ComplianceJsonPanel
              title="GRI Standards (305 emissions)"
              data={exportPack || modules.griStandards}
              filename="gri-305-emissions-pack.json"
            />
          </Stack>
        );
      case 'tcfd-issb':
        return (
          <Stack spacing={2}>
            <Button variant="outlined" onClick={() => loadExportPack('tcfd')}>
              Refresh TCFD / ISSB pack
            </Button>
            <ComplianceJsonPanel
              title="TCFD / IFRS S2 structure"
              data={exportPack || modules.tcfdIssb}
              filename="tcfd-issb-pack.json"
            />
          </Stack>
        );
      case 'supplier-portal':
        return (
          <Stack spacing={2}>
            <Card variant="outlined">
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  New buyer questionnaire
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={4}>
                    <TextField
                      label="Buyer name"
                      fullWidth
                      value={newQuestionnaire.buyerName}
                      onChange={(e) =>
                        setNewQuestionnaire({ ...newQuestionnaire, buyerName: e.target.value })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <FormControl fullWidth>
                      <InputLabel>Framework</InputLabel>
                      <Select
                        label="Framework"
                        value={newQuestionnaire.framework}
                        onChange={(e) =>
                          setNewQuestionnaire({
                            ...newQuestionnaire,
                            framework: e.target.value,
                          })
                        }
                      >
                        <MenuItem value="brsr_core">BRSR Core</MenuItem>
                        <MenuItem value="cdp">CDP</MenuItem>
                        <MenuItem value="csrd">CSRD</MenuItem>
                        <MenuItem value="ecovadis">EcoVadis</MenuItem>
                        <MenuItem value="custom">Custom</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <Button variant="contained" onClick={addQuestionnaire} disabled={saving}>
                      Add request
                    </Button>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Buyer</TableCell>
                  <TableCell>Framework</TableCell>
                  <TableCell>Status</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {((modules.supplierQuestionnaires as Record<string, unknown>[]) || []).map((q) => (
                  <TableRow key={String(q._id)}>
                    <TableCell>{String(q.buyerName)}</TableCell>
                    <TableCell>{String(q.framework)}</TableCell>
                    <TableCell>{complianceWorkflowStatusLabel(String(q.status))}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </Stack>
        );
      case 'eudr':
        return (
          <ComplianceJsonPanel
            title="EUDR due diligence skeleton"
            data={modules.eudr}
            filename="eudr-pack.json"
          />
        );
      case 'ecovadis':
        return (
          <Stack spacing={2}>
            <Button variant="outlined" onClick={() => loadExportPack('ecovadis')}>
              Refresh EcoVadis pack
            </Button>
            <ComplianceJsonPanel
              title="EcoVadis-aligned datapoints"
              data={exportPack || modules.ecovadis}
              filename="ecovadis-pack.json"
            />
          </Stack>
        );
      default:
        return null;
    }
  };

  return (
    <ComplianceTrackShell
      trackTitle={isEnterprise ? 'Global buyer disclosure' : 'Global export compliance'}
      trackDescription={
        isEnterprise
          ? 'CDP C1–C15, CSRD value-chain datapoints, TCFD/ISSB S2, and buyer questionnaire packs for listed and large enterprises.'
          : 'Requirements for Indian exporters: EU CBAM, product PCF, CSRD value-chain datapoints, CDP, TCFD/ISSB S2, buyer questionnaires, EUDR, and EcoVadis.'
      }
      trackPath={isEnterprise ? '/enterprise/compliance' : '/compliance/export'}
      sectionGroups={EXPORT_COMPLIANCE_GROUPS}
      activeSection={section}
      onSectionChange={setSection}
      period={period}
      onPeriodChange={setPeriod}
      loading={loading}
    >
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}
      {renderSection()}
    </ComplianceTrackShell>
  );
};

export default ExportComplianceTrack;
